  for (let j = 0; j < net.ab.length / 2; j++) { const a = net.prot[net.ab[2 * j]], b = net.prot[net.ab[2 * j + 1]]; if (a !== b) pairs.push(a, b); }
  const acc = new Float32Array(3 * NP), cnt = new Float32Array(NP);
