  const pick = () => { let x = rnd(); for (const k of KS) { x -= k.share; if (x < 0) return k.key; } return KS[KS.length - 1].key; };
  const P = { done: false, mols: [], nb: 0, miss: 0, i: 0, grid: new Map(), SB: null };
  const gk = (x, y, z) => x + 4096 * (y + 4096 * z);
