        let lo = 0, hi = R;
        for (let k = 0; k < 30; k++) { const m = (lo + hi) / 2; if (SLAB.rel(sh, [sh.c[0] + d[0] * m, sh.c[1] + d[1] * m, z]).q < 1) lo = m; else hi = m; }
        return [sh.c[0] + d[0] * lo, sh.c[1] + d[1] * lo, z];
